PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE action_feedback (
	id INTEGER NOT NULL, 
	action_id VARCHAR(50) NOT NULL, 
	feedback_id VARCHAR(100) NOT NULL, 
	feedback_type VARCHAR(50) NOT NULL, 
	linked_date DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(action_id) REFERENCES action_items (action_id)
);
CREATE TABLE action_items (
	action_id VARCHAR(50) NOT NULL, 
	theme_id VARCHAR(50) NOT NULL, 
	product_id VARCHAR(50) NOT NULL, 
	priority_score FLOAT NOT NULL, 
	priority_level VARCHAR(50) NOT NULL, 
	problem_description TEXT NOT NULL, 
	recommended_action TEXT NOT NULL, 
	assigned_team VARCHAR(100) NOT NULL, 
	owner VARCHAR(100) NOT NULL, 
	status VARCHAR(50) NOT NULL, 
	expected_impact VARCHAR(255) NOT NULL, 
	actual_impact TEXT, 
	created_date DATETIME NOT NULL, 
	due_date DATETIME NOT NULL, 
	resolved_date DATETIME, 
	PRIMARY KEY (action_id), 
	FOREIGN KEY(theme_id) REFERENCES themes (theme_id), 
	FOREIGN KEY(product_id) REFERENCES products (product_id)
);
CREATE TABLE channels (
	channel_id VARCHAR(50) NOT NULL, 
	channel_name VARCHAR(100) NOT NULL, 
	channel_type VARCHAR(50) NOT NULL, 
	description VARCHAR(255), 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (channel_id), 
	UNIQUE (channel_name)
);
CREATE TABLE customers (
	customer_id VARCHAR(50) NOT NULL, 
	full_name VARCHAR(200) NOT NULL, 
	email VARCHAR(200) NOT NULL, 
	segment VARCHAR(50) NOT NULL, 
	country VARCHAR(50) NOT NULL, 
	loyalty_tier VARCHAR(50) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (customer_id)
);
CREATE TABLE data_quality_issues (
	issue_id VARCHAR(50) NOT NULL, 
	source_record_id VARCHAR(100) NOT NULL, 
	source_record_type VARCHAR(50) NOT NULL, 
	issue_type VARCHAR(100) NOT NULL, 
	severity VARCHAR(50) NOT NULL, 
	expected_result TEXT NOT NULL, 
	actual_result TEXT NOT NULL, 
	detection_timestamp DATETIME NOT NULL, 
	resolution_status VARCHAR(50) NOT NULL, 
	resolution_notes TEXT, 
	PRIMARY KEY (issue_id)
);
CREATE TABLE feedback_sentiments (
	id INTEGER NOT NULL, 
	feedback_id VARCHAR(100) NOT NULL, 
	feedback_type VARCHAR(50) NOT NULL, 
	predicted_sentiment VARCHAR(50) NOT NULL, 
	confidence_score FLOAT NOT NULL, 
	model_version VARCHAR(50) NOT NULL, 
	explanation TEXT, 
	review_status VARCHAR(50) NOT NULL, 
	processing_timestamp DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE feedback_themes (
	id INTEGER NOT NULL, 
	feedback_id VARCHAR(100) NOT NULL, 
	feedback_type VARCHAR(50) NOT NULL, 
	theme_id VARCHAR(50) NOT NULL, 
	confidence FLOAT NOT NULL, 
	classification_method VARCHAR(50) NOT NULL, 
	model_version VARCHAR(50) NOT NULL, 
	is_human_reviewed BOOLEAN NOT NULL, 
	reviewed_by VARCHAR(100), 
	review_timestamp DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(theme_id) REFERENCES themes (theme_id)
);
CREATE TABLE model_evaluations (
	eval_id VARCHAR(50) NOT NULL, 
	model_type VARCHAR(50) NOT NULL, 
	model_version VARCHAR(50) NOT NULL, 
	evaluation_dataset VARCHAR(50) NOT NULL, 
	accuracy FLOAT, 
	precision_macro FLOAT, 
	recall_macro FLOAT, 
	f1_macro FLOAT, 
	f1_micro FLOAT, 
	hamming_loss FLOAT, 
	metrics_json TEXT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (eval_id)
);
CREATE TABLE processing_runs (
	run_id VARCHAR(50) NOT NULL, 
	run_type VARCHAR(50) NOT NULL, 
	start_time DATETIME NOT NULL, 
	end_time DATETIME, 
	records_processed INTEGER NOT NULL, 
	records_flagged INTEGER NOT NULL, 
	status VARCHAR(50) NOT NULL, 
	config_json TEXT, 
	PRIMARY KEY (run_id)
);
CREATE TABLE products (
	product_id VARCHAR(50) NOT NULL, 
	product_name VARCHAR(200) NOT NULL, 
	category VARCHAR(100) NOT NULL, 
	sku VARCHAR(100) NOT NULL, 
	price FLOAT NOT NULL, 
	release_date DATETIME NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (product_id), 
	UNIQUE (sku)
);
CREATE TABLE reviews (
	review_id VARCHAR(50) NOT NULL, 
	customer_id VARCHAR(50) NOT NULL, 
	product_id VARCHAR(50) NOT NULL, 
	channel_id VARCHAR(50) NOT NULL, 
	rating INTEGER NOT NULL, 
	title VARCHAR(255), 
	review_text TEXT NOT NULL, 
	review_date DATETIME NOT NULL, 
	verified_purchase BOOLEAN NOT NULL, 
	ground_truth_sentiment VARCHAR(50), 
	ground_truth_theme_ids VARCHAR(255), 
	PRIMARY KEY (review_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id), 
	FOREIGN KEY(product_id) REFERENCES products (product_id), 
	FOREIGN KEY(channel_id) REFERENCES channels (channel_id)
);
CREATE TABLE sentiment_labels (
	label_code VARCHAR(50) NOT NULL, 
	description VARCHAR(255) NOT NULL, 
	polarity_score FLOAT NOT NULL, 
	PRIMARY KEY (label_code)
);
CREATE TABLE sentiment_shift_alerts (
	alert_id VARCHAR(50) NOT NULL, 
	dimension_type VARCHAR(50) NOT NULL, 
	dimension_id VARCHAR(100) NOT NULL, 
	period_start DATETIME NOT NULL, 
	period_end DATETIME NOT NULL, 
	baseline_negative_rate FLOAT NOT NULL, 
	current_negative_rate FLOAT NOT NULL, 
	percentage_change FLOAT NOT NULL, 
	feedback_volume INTEGER NOT NULL, 
	severity VARCHAR(50) NOT NULL, 
	summary TEXT NOT NULL, 
	detected_at DATETIME NOT NULL, 
	PRIMARY KEY (alert_id)
);
CREATE TABLE state_change_events (
	id INTEGER NOT NULL, 
	entity_type VARCHAR(50) NOT NULL, 
	entity_id VARCHAR(100) NOT NULL, 
	previous_state VARCHAR(100), 
	new_state VARCHAR(100) NOT NULL, 
	changed_by VARCHAR(100) NOT NULL, 
	change_reason TEXT, 
	change_timestamp DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE support_messages (
	message_id VARCHAR(100) NOT NULL, 
	ticket_id VARCHAR(50) NOT NULL, 
	customer_id VARCHAR(50) NOT NULL, 
	product_id VARCHAR(50) NOT NULL, 
	channel_id VARCHAR(50) NOT NULL, 
	sender_type VARCHAR(50) NOT NULL, 
	message_text TEXT NOT NULL, 
	message_date DATETIME NOT NULL, 
	priority VARCHAR(50) NOT NULL, 
	ground_truth_sentiment VARCHAR(50), 
	ground_truth_theme_ids VARCHAR(255), 
	PRIMARY KEY (message_id), 
	FOREIGN KEY(ticket_id) REFERENCES tickets (ticket_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id), 
	FOREIGN KEY(product_id) REFERENCES products (product_id), 
	FOREIGN KEY(channel_id) REFERENCES channels (channel_id)
);
CREATE TABLE survey_responses (
	response_id VARCHAR(100) NOT NULL, 
	survey_id VARCHAR(50) NOT NULL, 
	customer_id VARCHAR(50) NOT NULL, 
	product_id VARCHAR(50) NOT NULL, 
	channel_id VARCHAR(50) NOT NULL, 
	rating INTEGER NOT NULL, 
	response_text TEXT NOT NULL, 
	response_date DATETIME NOT NULL, 
	ground_truth_sentiment VARCHAR(50), 
	ground_truth_theme_ids VARCHAR(255), 
	PRIMARY KEY (response_id), 
	FOREIGN KEY(survey_id) REFERENCES surveys (survey_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id), 
	FOREIGN KEY(product_id) REFERENCES products (product_id), 
	FOREIGN KEY(channel_id) REFERENCES channels (channel_id)
);
CREATE TABLE surveys (
	survey_id VARCHAR(50) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	description TEXT, 
	target_audience VARCHAR(100) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (survey_id)
);
CREATE TABLE themes (
	theme_id VARCHAR(50) NOT NULL, 
	theme_name VARCHAR(100) NOT NULL, 
	parent_theme_id VARCHAR(50), 
	description TEXT NOT NULL, 
	keywords TEXT NOT NULL, 
	default_severity VARCHAR(50) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	effective_start_date DATETIME NOT NULL, 
	effective_end_date DATETIME, 
	PRIMARY KEY (theme_id), 
	FOREIGN KEY(parent_theme_id) REFERENCES themes (theme_id)
);
CREATE TABLE tickets (
	ticket_id VARCHAR(50) NOT NULL, 
	customer_id VARCHAR(50) NOT NULL, 
	product_id VARCHAR(50) NOT NULL, 
	channel_id VARCHAR(50) NOT NULL, 
	subject VARCHAR(255) NOT NULL, 
	status VARCHAR(50) NOT NULL, 
	created_at DATETIME NOT NULL, 
	resolved_at DATETIME, 
	PRIMARY KEY (ticket_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id), 
	FOREIGN KEY(product_id) REFERENCES products (product_id), 
	FOREIGN KEY(channel_id) REFERENCES channels (channel_id)
);
CREATE UNIQUE INDEX ix_customers_email ON customers (email);
CREATE INDEX ix_customers_customer_id ON customers (customer_id);
CREATE INDEX ix_products_product_id ON products (product_id);
CREATE INDEX ix_products_category ON products (category);
CREATE INDEX ix_channels_channel_id ON channels (channel_id);
CREATE INDEX ix_surveys_survey_id ON surveys (survey_id);
CREATE UNIQUE INDEX ix_themes_theme_name ON themes (theme_name);
CREATE INDEX ix_themes_theme_id ON themes (theme_id);
CREATE UNIQUE INDEX ix_feedback_sentiment_unique ON feedback_sentiments (feedback_id, feedback_type);
CREATE INDEX ix_feedback_sentiments_feedback_type ON feedback_sentiments (feedback_type);
CREATE INDEX ix_feedback_sentiments_predicted_sentiment ON feedback_sentiments (predicted_sentiment);
CREATE INDEX ix_feedback_sentiments_feedback_id ON feedback_sentiments (feedback_id);
CREATE INDEX ix_state_change_events_entity_type ON state_change_events (entity_type);
CREATE INDEX ix_state_change_events_entity_id ON state_change_events (entity_id);
CREATE INDEX ix_data_quality_issues_issue_type ON data_quality_issues (issue_type);
CREATE INDEX ix_data_quality_issues_source_record_id ON data_quality_issues (source_record_id);
CREATE INDEX ix_data_quality_issues_issue_id ON data_quality_issues (issue_id);
CREATE INDEX ix_processing_runs_run_id ON processing_runs (run_id);
CREATE INDEX ix_model_evaluations_eval_id ON model_evaluations (eval_id);
CREATE INDEX ix_sentiment_shift_alerts_alert_id ON sentiment_shift_alerts (alert_id);
CREATE INDEX ix_survey_responses_customer_id ON survey_responses (customer_id);
CREATE INDEX ix_survey_responses_survey_id ON survey_responses (survey_id);
CREATE INDEX ix_survey_responses_channel_id ON survey_responses (channel_id);
CREATE INDEX ix_survey_responses_response_date ON survey_responses (response_date);
CREATE INDEX ix_survey_responses_product_id ON survey_responses (product_id);
CREATE INDEX ix_survey_responses_response_id ON survey_responses (response_id);
CREATE INDEX ix_reviews_customer_id ON reviews (customer_id);
CREATE INDEX ix_reviews_review_date ON reviews (review_date);
CREATE INDEX ix_reviews_review_id ON reviews (review_id);
CREATE INDEX ix_reviews_product_id ON reviews (product_id);
CREATE INDEX ix_reviews_channel_id ON reviews (channel_id);
CREATE INDEX ix_tickets_channel_id ON tickets (channel_id);
CREATE INDEX ix_tickets_customer_id ON tickets (customer_id);
CREATE INDEX ix_tickets_product_id ON tickets (product_id);
CREATE INDEX ix_tickets_ticket_id ON tickets (ticket_id);
CREATE INDEX ix_action_items_theme_id ON action_items (theme_id);
CREATE INDEX ix_action_items_product_id ON action_items (product_id);
CREATE INDEX ix_action_items_action_id ON action_items (action_id);
CREATE UNIQUE INDEX ix_feedback_theme_unique ON feedback_themes (feedback_id, feedback_type, theme_id);
CREATE INDEX ix_feedback_themes_feedback_id ON feedback_themes (feedback_id);
CREATE INDEX ix_feedback_themes_feedback_type ON feedback_themes (feedback_type);
CREATE INDEX ix_feedback_themes_theme_id ON feedback_themes (theme_id);
CREATE INDEX ix_support_messages_product_id ON support_messages (product_id);
CREATE INDEX ix_support_messages_message_id ON support_messages (message_id);
CREATE INDEX ix_support_messages_customer_id ON support_messages (customer_id);
CREATE INDEX ix_support_messages_ticket_id ON support_messages (ticket_id);
CREATE INDEX ix_support_messages_message_date ON support_messages (message_date);
CREATE INDEX ix_support_messages_channel_id ON support_messages (channel_id);
CREATE UNIQUE INDEX ix_action_feedback_unique ON action_feedback (action_id, feedback_id, feedback_type);
CREATE INDEX ix_action_feedback_action_id ON action_feedback (action_id);
CREATE INDEX ix_action_feedback_feedback_id ON action_feedback (feedback_id);
COMMIT;
