INSERT INTO "action_items" VALUES('ACT-000001','THEME-000001','PROD-000005',72.5,'HIGH','Recurring hardware quality flaws and premature component wear.','Enforce strict incoming QC tolerances at supplier assembly plants and replace brittle plastic molds with reinforced composites.','Engineering','Engineering Lead','OPEN','Reduces defective product returns by an estimated 45% within 60 days.',NULL,'2026-11-01 09:29:08.783056','2026-11-22 09:29:08.783056',NULL);
INSERT INTO "action_items" VALUES('ACT-000002','THEME-000017','PROD-000001',71.3,'HIGH','Firmware regression bug throwing uncaught null pointer exceptions.','Deploy hotfix patch v2.4.1 to staging, run automated regression suite, and roll out canary release.','Engineering','Engineering Lead','OPEN','Eliminates fatal crash exceptions for 100% of active sessions.',NULL,'2026-11-01 09:29:08.783056','2026-11-22 09:29:08.783056',NULL);
INSERT INTO "action_items" VALUES('ACT-000003','THEME-000017','PROD-000005',71.3,'HIGH','Firmware regression bug throwing uncaught null pointer exceptions.','Deploy hotfix patch v2.4.1 to staging, run automated regression suite, and roll out canary release.','Engineering','Engineering Lead','OPEN','Eliminates fatal crash exceptions for 100% of active sessions.',NULL,'2026-11-01 09:29:08.783056','2026-11-22 09:29:08.783056',NULL);
INSERT INTO "action_items" VALUES('ACT-000004','THEME-000011','PROD-000006',68.2,'MEDIUM','Unscheduled service interruptions and random device restarts.','Conduct chaos testing, harden failover database clusters, and implement auto-restart watchdog.','Engineering','Engineering Lead','OPEN','Guarantees 99.95% system availability.',NULL,'2026-11-01 09:29:08.783056','2026-11-22 09:29:08.783056',NULL);
INSERT INTO "action_items" VALUES('ACT-000005','THEME-000005','PROD-000005',68.1,'MEDIUM','Memory leaks and high CPU usage causing frequent crashes and slow dashboard renders.','Profile client memory consumption, refactor heavy table virtualizers, and implement edge caching.','Engineering','Engineering Lead','OPEN','Reduces client crash rate from 2.4% to < 0.2% and speeds up load times by 3x.',NULL,'2026-11-01 09:29:08.783056','2026-11-22 09:29:08.783056',NULL);
INSERT INTO "action_items" VALUES('ACT-000006','THEME-000007','PROD-000006',68.0,'MEDIUM','Spike in double charges and false credit card declines during checkout.','Implement idempotent checkout tokens and configure automated secondary payment gateway failover.','Finance','Finance Lead','OPEN','Recovers $120k in abandoned cart transactions and eliminates double billing.',NULL,'2026-11-01 09:29:08.783056','2026-11-22 09:29:08.783056',NULL);
