INSERT INTO "themes" VALUES('THEME-000001','Product Quality',NULL,'Feedback concerning the physical or functional quality of the product.','quality,build,durability,finish,material,hardware,defect,flaw,premium,cheap','HIGH',1,'2026-11-01 09:28:46.792177',NULL);
INSERT INTO "themes" VALUES('THEME-000002','Pricing',NULL,'Comments related to price-to-value, subscription costs, discounts and promos.','price,expensive,cost,cheap,worth,value,discount,overpriced,affordable,deal','MEDIUM',1,'2026-11-01 09:28:46.792183',NULL);
INSERT INTO "themes" VALUES('THEME-000003','Customer Support',NULL,'Quality, responsiveness, and demeanor of customer service representatives.','support,agent,representative,call,ticket,help,chat,service,rude,helpful,response','HIGH',1,'2026-11-01 09:28:46.792184',NULL);
INSERT INTO "themes" VALUES('THEME-000004','Delivery Experience',NULL,'Shipment timeliness, packaging integrity, and tracking accuracy.','delivery,shipping,courier,package,delayed,tracking,damaged,fast,late,arrival','HIGH',1,'2026-11-01 09:28:46.792186',NULL);
INSERT INTO "themes" VALUES('THEME-000005','Application Performance',NULL,'Mobile and desktop application responsiveness, speed, and resource usage.','lag,slow,fast,freeze,crash,latency,speed,responsive,loading,timeout,memory','HIGH',1,'2026-11-01 09:28:46.792187',NULL);
INSERT INTO "themes" VALUES('THEME-000006','User Experience',NULL,'Ease of navigation, visual design, and user journey simplicity.','ui,ux,interface,navigation,intuitive,confusing,design,layout,button,usability','MEDIUM',1,'2026-11-01 09:28:46.792188',NULL);
INSERT INTO "themes" VALUES('THEME-000007','Payment Issues',NULL,'Payment gateway errors, double charges, and checkout transaction failures.','payment,card,failed,checkout,charge,transaction,gateway,stripe,declined,double','CRITICAL',1,'2026-11-01 09:28:46.792189',NULL);
INSERT INTO "themes" VALUES('THEME-000008','Refunds','THEME-000007','Processing speed and resolution of refund and chargeback requests.','refund,return,reimbursement,money back,credit,reverse,claim','HIGH',1,'2026-11-01 09:28:46.792190',NULL);
INSERT INTO "themes" VALUES('THEME-000009','Account Management',NULL,'User authentication, profile details, password resets, and account security.','login,password,account,profile,sign in,auth,reset,verify,2fa,blocked','HIGH',1,'2026-11-01 09:28:46.792191',NULL);
INSERT INTO "themes" VALUES('THEME-000010','Documentation',NULL,'Clarity and completeness of user guides, manuals, and developer documentation.','manual,docs,documentation,guide,tutorial,faq,api docs,instructions,missing docs','LOW',1,'2026-11-01 09:28:46.792192',NULL);
INSERT INTO "themes" VALUES('THEME-000011','Product Reliability','THEME-000001','Continuous uptime, lack of unintended resets, and dependable daily operation.','reliable,crash,stable,reboot,shut down,glitch,uptime,outage,disconnect','CRITICAL',1,'2026-11-01 09:28:46.792194',NULL);
INSERT INTO "themes" VALUES('THEME-000012','Feature Requests',NULL,'Customer proposals for new capabilities, integrations, and enhancements.','wish,suggest,add,feature,need,integration,option,export,support for,ability to','LOW',1,'2026-11-01 09:28:46.792195',NULL);
INSERT INTO "themes" VALUES('THEME-000013','Security and Privacy',NULL,'User data privacy, permission requests, encryption, and compliance matters.','privacy,security,data,leak,breach,permission,tracking,cookie,gdpr,unauthorized','CRITICAL',1,'2026-11-01 09:28:46.792196',NULL);
INSERT INTO "themes" VALUES('THEME-000014','Availability',NULL,'Item stock status, cloud service region availability, and inventory levels.','stock,out of stock,available,sold out,backorder,restock,store,inventory','MEDIUM',1,'2026-11-01 09:28:46.792197',NULL);
INSERT INTO "themes" VALUES('THEME-000015','Communication','THEME-000003','Proactiveness and clarity of company communications, status updates, and alerts.','email,notify,notification,update,sms,alert,spam,silence,uninformed','MEDIUM',1,'2026-11-01 09:28:46.792198',NULL);
INSERT INTO "themes" VALUES('THEME-000016','Installation',NULL,'Hardware assembly, unboxing, software onboarding, and initial pairing.','install,setup,unboxing,configure,pairing,assembly,drivers,first use','MEDIUM',1,'2026-11-01 09:28:46.792199',NULL);
INSERT INTO "themes" VALUES('THEME-000017','Technical Issues','THEME-000005','Uncaught errors, system bugs, firmware regressions, and technical glitches.','bug,error,stack,exception,broken,malfunction,corrupt,firmware,patch','HIGH',1,'2026-11-01 09:28:46.792200',NULL);
INSERT INTO "themes" VALUES('THEME-000018','Subscription Management','THEME-000002','Managing monthly/yearly recurring subscriptions, renewals, and cancellations.','renew,cancel,subscription,plan,tier,auto-renew,upgrade,downgrade,billing cycle','HIGH',1,'2026-11-01 09:28:46.792201',NULL);
